// Obtenemos los datos de Open Library Search de forma segura
let searchDoc = {};
try {
  searchDoc = $('Open Library Search').first().json.docs[0] || {};
} catch (e) {
  searchDoc = {};
}

// Obtenemos el ISBN
let isbn = '';
try {
  const input = $('ISBN Input1').first().json;
  isbn = input.isbn || input.valuel || input.value1 || '9788419834232';
} catch (e) {
  isbn = '9788419834232';
}

const workData = $json || {};

const coverId = searchDoc.cover_i;
const coverUrl = coverId 
  ? `https://covers.openlibrary.org/b/id/${coverId}-L.jpg` 
  : `https://covers.openlibrary.org/b/isbn/${isbn}-L.jpg`;

let description = 'Sin descripción disponible.';
if (workData.description) {
  if (typeof workData.description === 'object') {
    description = workData.description.value || description;
  } else {
    description = workData.description;
  }
}

const author = (searchDoc.author_name && searchDoc.author_name.length > 0) 
  ? searchDoc.author_name[0] 
  : 'Autor desconocido';

const year = searchDoc.first_publish_year || new Date().getFullYear();
const subjects = (workData.subjects || []).slice(0, 5).map(s => s.name || s);

function mapGenre(subjects) {
  const genreMap = {
    'thriller': 'Novela negra',
    'mystery': 'Novela negra',
    'fantasy': 'Fantasía',
    'horror': 'Terror',
    'science': 'Ciencia ficción',
    'children': 'Infantil',
    'romance': 'Romance',
    'history': 'Historia',
    'biography': 'Biografía',
    'poetry': 'Poesía',
    'drama': 'Teatro',
    'fiction': 'Novela'
  };
  for (const subject of subjects) {
    const lower = String(subject).toLowerCase();
    for (const [key, value] of Object.entries(genreMap)) {
      if (lower.includes(key)) return value;
    }
  }
  return 'Novela';
}

const genre = mapGenre(subjects);

return {
  isbn: String(isbn),
  title: searchDoc.title || 'Título desconocido',
  author: author,
  year: Number(year) || 2024,
  genre: genre,
  coverUrl: coverUrl,
  description: String(description).substring(0, 2000),
  fechaEntrada: new Date().toISOString().split('T')[0]
};

const item = ($json.items && $json.items.length > 0) ? $json.items[0] : {};
const info = item.volumeInfo || {};

let isbn = '';
try {
  isbn = $('ISBN Input1').first().json.isbn;
} catch (e) {
  isbn = '';
}

const title = info.title || 'Título desconocido';
const author = (info.authors && info.authors.length > 0) ? info.authors.join(', ') : 'Autor desconocido';

let year = 2024;
if (info.publishedDate) {
  const parsed = parseInt(info.publishedDate.substring(0, 4));
  if (!isNaN(parsed)) year = parsed;
}

const description = info.description || 'Sin descripción disponible.';

// Portada segura en https
let coverUrl = '';
if (info.imageLinks) {
  const img = info.imageLinks.thumbnail || info.imageLinks.smallThumbnail || '';
  coverUrl = img.replace('http://', 'https://');
} else {
  coverUrl = `https://covers.openlibrary.org/b/isbn/${isbn}-L.jpg`;
}

// Mapeo de género según categorías de Google Books
const categories = info.categories || [];
function mapGenre(cats) {
  const genreMap = {
    'thriller': 'Novela negra',
    'mystery': 'Novela negra',
    'suspense': 'Novela negra',
    'crime': 'Novela negra',
    'detective': 'Novela negra',
    'fantasy': 'Fantasía',
    'horror': 'Terror',
    'science fiction': 'Ciencia ficción',
    'sci-fi': 'Ciencia ficción',
    'juvenile': 'Infantil',
    'children': 'Infantil',
    'infantil': 'Infantil',
    'romance': 'Romance',
    'history': 'Historia',
    'historia': 'Historia',
    'biography': 'Biografía',
    'biografía': 'Biografía',
    'poetry': 'Poesía',
    'poesía': 'Poesía',
    'drama': 'Teatro',
    'teatro': 'Teatro',
    'philosophy': 'Filosofía',
    'filosofía': 'Filosofía',
    'fiction': 'Novela',
    'ficción': 'Novela'
  };
  for (const cat of cats) {
    const lower = String(cat).toLowerCase();
    for (const [key, value] of Object.entries(genreMap)) {
      if (lower.includes(key)) return value;
    }
  }
  return 'Novela';
}

const genre = mapGenre(categories);

return {
  isbn: String(isbn),
  title: title,
  author: author,
  year: Number(year) || 2024,
  genre: genre,
  coverUrl: coverUrl,
  description: String(description).substring(0, 2000),
  fechaEntrada: new Date().toISOString().split('T')[0]
};

const notionPage = $json;

let bookData = {};
try {
  if ($('Normalizar Datos').isExecuted) {
    bookData = $('Normalizar Datos').first().json;
  } else if ($('Normalizar Google Books').isExecuted) {
    bookData = $('Normalizar Google Books').first().json;
  }
} catch (e) {
  try {
    bookData = $('Normalizar Google Books').first().json;
  } catch (err) {
    bookData = {};
  }
}

return {
  success: true,
  message: `Libro creado: ${bookData.title || 'Libro registrado'}`,
  isbn: bookData.isbn || '',
  author: bookData.author || '',
  notionUrl: notionPage.url || 'URL no disponible',
  genre: bookData.genre || '',
  coverUrl: bookData.coverUrl || ''
};

let isbn = '';
try {
  isbn = $('ISBN Input1').first().json.isbn;
} catch (e) {
  isbn = 'Desconocido';
}

return {
  success: false,
  message: `No se encontró el libro con ISBN ${isbn} ni en Open Library ni en Google Books`,
  isbn: isbn,
  suggestion: 'Introduce los datos manualmente en Notion o comprueba el número de ISBN.'
};
